namespace internal {
/**
 * Returns true iff the 3 points are collinear. 3 points are collinear
 * iff triangle area is zero
 */
CG3_INLINE bool areCollinearPoints(
        const Point2d& a,
        const Point2d& b,
        const Point2d& c,
        const double eps)
{
    return cg3::epsilonEqual(
                (b.x() - a.x()) * (c.y() - a.y()),
                (c.x() - a.x()) * (b.y() - a.y()),
                eps);
}

/**
 * Returns true iff point c lies on the closed segment ab.
 * Assumes it is already known that abc are collinear.
 */
CG3_INLINE bool isBetween(
        const Point2d& a,
        const Point2d& b,
        const Point2d& c,
        const double eps)
{
   /* If ab not vertical, check betweenness on x; else on y. */
   if (!cg3::epsilonEqual(a.x(), b.x(), eps))
      return ((a.x() <= c.x()) && (c.x() <= b.x())) ||
             ((a.x() >= c.x()) && (c.x() >= b.x()));
   else
      return ((a.y() <= c.y()) && (c.y() <= b.y())) ||
             ((a.y() >= c.y()) && (c.y() >= b.y()));
