const double eps = cg3::CG3_EPSILON;

for (size_t i = 0; i < segments.size(); ++i) {
    for (size_t j = i + 1; j < segments.size(); ++j) {
        const Segment2d& seg1 = segments[i];
        const Segment2d& seg2 = segments[j];

        Point2d a = seg1.p1();
        Point2d b = seg1.p2();
        Point2d c = seg2.p1();
        Point2d d = seg2.p2();

        // Check for identical segments
        if ((cg3::epsilonEqual(a, c, eps) && cg3::epsilonEqual(b, d, eps)) ||
            (cg3::epsilonEqual(a, d, eps) && cg3::epsilonEqual(b, c, eps))) {
            // Add one point from the segment (avoid duplicates)
            intersections.push_back(a);
            continue;
        }

        // Check for endpoint intersections
        if (cg3::epsilonEqual(a, c, eps) || cg3::epsilonEqual(a, d, eps)) {
            intersections.push_back(a);
            continue;
        }
        if (cg3::epsilonEqual(b, c, eps) || cg3::epsilonEqual(b, d, eps)) {
            intersections.push_back(b);
            continue;
        }

        // Calculate denominator for parametric equations
        double denom = a.x() * (d.y() - c.y()) + b.x() * (c.y() - d.y()) + 
                      d.x() * (b.y() - a.y()) + c.x() * (a.y() - b.y());

        // Check if segments are parallel
        if (cg3::epsilonEqual(denom, 0.0, eps)) {
            // Check if collinear and overlapping
            if (internal::areCollinearPoints(a, b, c, eps)) {
                if (internal::isBetween(a, b, c, eps)) {
                    intersections.push_back(c);
                } else if (internal::isBetween(a, b, d, eps)) {
                    intersections.push_back(d);
                } else if (internal::isBetween(c, d, a, eps)) {
                    intersections.push_back(a);
                } else if (internal::isBetween(c, d, b, eps)) {
                    intersections.push_back(b);
                }
            }
            continue;
        }

        // Calculate parameters for intersection
        double num_s = a.x() * (d.y() - c.y()) + c.x() * (a.y() - d.y()) + d.x() * (c.y() - a.y());
        double s = num_s / denom;

        double num_t = -(a.x() * (c.y() - b.y()) + b.x() * (a.y() - c.y()) + c.x() * (b.y() - a.y()));
        double t = num_t / denom;

        // Check if intersection is within both segments
        if (s >= -eps && s <= 1.0 + eps && t >= -eps && t <= 1.0 + eps) {
            // Calculate intersection point
            double x = a.x() + s * (b.x() - a.x());
            double y = a.y() + s * (b.y() - a.y());
            Point2d intersection(x, y);

            // Check if this intersection is already in the list (avoid duplicates)
            bool duplicate = false;
            for (const Point2d& existing : intersections) {
                if (cg3::epsilonEqual(existing.x(), x, eps) && 
                    cg3::epsilonEqual(existing.y(), y, eps)) {
                    duplicate = true;
                    break;
                }
            }
            if (!duplicate) {
                intersections.push_back(intersection);
            }
        }
    }
